import * as THREE from 'three/webgpu';
import { float, vec3, mix, smoothstep } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const colors = {
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  const cellPadding = 0.5;
  const cellDepth = 0.06;

  const cells = [
    {
      width: 3.25,
      height: 3.5,
      x: -1.375,
      y: 0,
      value: "0.002 mm",
      label: "Case tolerance, CNC pass",
      valueFontSize: 124,
    },
    {
      width: 2.0,
      height: 1.625,
      x: 1.25,
      y: 0.9375,
      value: "38 h",
      label: "Power reserve, NA-01",
      valueFontSize: 68,
    },
    {
      width: 2.0,
      height: 1.625,
      x: 1.25,
      y: -0.9375,
      value: "214",
      label: "Components per calibre",
      valueFontSize: 68,
    },
  ];

  function createCellMaterial() {
    const material = new THREE.MeshStandardNodeMaterial({
      colorSpace: THREE.LinearSRGBColorSpace,
      transparent: true,
    });

    const gradColor = mix(
      vec3(0.063, 0.063, 0.092),
      vec3(0.102, 0.102, 0.133),
      smoothstep(float(0), float(1), material.vUv.y)
    );

    material.colorNode = gradColor;
    material.metalness = float(0.45);
    material.roughness = float(0.5);
    material.clearcoat = float(0.2);
    material.opacity = float(1);

    return material;
  }

  function createCell(cellDef) {
    const cellGroup = new THREE.Group();

    const geometry = new THREE.BoxGeometry(cellDef.width, cellDef.height, cellDepth);
    const material = createCellMaterial();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.z = cellDepth / 2;
    cellGroup.add(mesh);

    const tickGeometry = new THREE.PlaneGeometry(0.4, 0.05);
    const tickMaterial = new THREE.MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: float(1.3),
    });
    const tickMesh = new THREE.Mesh(tickGeometry, tickMaterial);
    const tickX = -cellDef.width / 2 + cellPadding + 0.2;
    const tickY = cellDef.height / 2 - cellPadding - 0.025;
    tickMesh.position.set(tickX, tickY, cellDepth + 0.001);
    cellGroup.add(tickMesh);

    cellGroup.position.set(cellDef.x, cellDef.y, 0);
    return cellGroup;
  }

  const cellGroups = cells.map(createCell);
  cellGroups.forEach((g) => group.add(g));

  cellGroups.forEach((cellGroup, idx) => {
    const cellDef = cells[idx];
    const baseZ = cellDepth + 0.01;
    const valueX = -cellDef.width / 2 + cellPadding;
    const valueY = cellDef.height / 2 - cellPadding - 0.3;

    const valueMesh = ctx.fontAtlas.createMesh({
      text: cellDef.value,
      font: "Lora",
      fontSize: cellDef.valueFontSize,
      fontWeight: 600,
      color: colors.paper,
    });
    if (valueMesh) {
      valueMesh.position.set(valueX, valueY, baseZ);
      valueMesh.scale.set(0.01, 0.01, 0.01);
      cellGroup.add(valueMesh);
    }

    const labelMesh = ctx.fontAtlas.createMesh({
      text: cellDef.label,
      font: "JetBrains Mono",
      fontSize: 18,
      fontWeight: 400,
      color: colors.paper,
      letterSpacing: 0.08,
    });
    if (labelMesh) {
      labelMesh.position.set(valueX, valueY - 0.4, baseZ);
      labelMesh.scale.set(0.01, 0.01, 0.01);
      cellGroup.add(labelMesh);
    }
  });

  const headerMesh = ctx.fontAtlas.createMesh({
    text: "ATELIER METRICS / Q2 2026",
    font: "JetBrains Mono",
    fontSize: 18,
    fontWeight: 700,
    color: colors.paper,
    letterSpacing: 0.12,
  });
  if (headerMesh) {
    headerMesh.position.set(-2.75, 2.0, 0.1);
    headerMesh.scale.set(0.01, 0.01, 0.01);
    group.add(headerMesh);
  }

  const timelines = [];

  cellGroups.forEach((cellGroup, idx) => {
    const startY = cellGroup.position.y;
    cellGroup.position.y += 0.2;

    const tl = gsap.to(cellGroup.position, {
      y: startY,
      duration: 0.5,
      ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
      delay: idx * 0.08,
    });

    cellGroup.traverse((child) => {
      if (child.material && child.material.opacity !== undefined) {
        child.material.opacity = 0;
        gsap.to(child.material, {
          opacity: 1,
          duration: 0.5,
          ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
          delay: idx * 0.08,
        });
      }
    });

    timelines.push(tl);
  });

  cellGroups.forEach((cellGroup) => {
    let pressTimeline = null;
    let settleTimeline = null;

    cellGroup.userData.handlers = {
      pointerenter: () => {
        if (pressTimeline) pressTimeline.kill();
        if (settleTimeline) settleTimeline.kill();

        pressTimeline = gsap.to(cellGroup.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: "back.out",
        });
        timelines.push(pressTimeline);
      },
      pointerleave: () => {
        if (pressTimeline) pressTimeline.kill();
        if (settleTimeline) settleTimeline.kill();

        settleTimeline = gsap.to(cellGroup.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.9,
          ease: "cubic-bezier(0.165,0.84,0.44,1)",
        });
        timelines.push(settleTimeline);
      },
    };
  });

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });

    cellGroups.forEach((cellGroup) => {
      cellGroup.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    });
  };

  return group;
}
